<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Download, Refresh, Printer } from '@element-plus/icons-vue'
import { useApp } from '../store'
import { api, download, query } from '../api'
import { monthStart, today, money, quantity } from '../utils'
import DataTable from '../components/DataTable.vue'
import Chart from '../components/Chart.vue'
const app = useApp(), category = ref('sales'), group = ref('date'), dates = ref([monthStart(),today()]), rows = ref<any[]>([]), busy = ref(false)
const categories = [{key:'sales',name:'销售与毛利'},{key:'purchase',name:'采购分析'},{key:'operations',name:'经营分析'},{key:'sales_returns',name:'销售退货'},{key:'purchase_returns',name:'采购退货'},{key:'inventory',name:'库存分析'},{key:'inventory_count',name:'盘点差异'},{key:'ar',name:'客户应收'},{key:'ap',name:'供应商应付'}]
const isBusiness = computed(() => ['sales','purchase','sales_returns','purchase_returns'].includes(category.value))
const isSales = computed(() => category.value.startsWith('sales'))
const hasDates = computed(() => isBusiness.value || ['operations','inventory_count'].includes(category.value))
const groups = computed(() => [{key:'date',name:'按日统计'},{key:'month',name:'按月统计'},{key:'product',name:'商品排行'},{key:'partner',name:isSales.value ? '客户排行' : '供应商排行'},{key:'employee',name:'业务员排行'},{key:'flow',name:'业务 / 退回'},...(isSales.value ? [{key:'channel',name:'销售渠道'}] : [])])
function params() {return {category:category.value,group:group.value,start:dates.value?.[0],end:dates.value?.[1]}}
async function load(){busy.value=true;try{rows.value=(await api('/reports?'+query(params()))).items}catch{}finally{busy.value=false}}
watch(category,()=>{group.value='date';load()});watch(group,load);watch(()=>app.tick,load);onMounted(load)
const totals = computed(()=>({amount:rows.value.reduce((s,r)=>s+Number(r.amount||0),0),quantity:rows.value.reduce((s,r)=>s+Number(r.quantity||0),0),profit:rows.value.reduce((s,r)=>s+Number(r.profit||0),0),value:rows.value.reduce((s,r)=>s+Number(r.value||0),0),total:rows.value.reduce((s,r)=>s+Number(r.total||0),0)}))
const columns = computed(()=>{
  if(category.value==='operations')return [{key:'period',label:'月份',width:110},...[['sales','净销售额'],['purchase','净采购额'],['cash_received','净收款'],['cash_paid','净付款']].map(([key,label])=>({key,label,type:'money',minWidth:135,hidden:!app.amountVisible})),{key:'collection_rate',label:'当期回款率',minWidth:125,hidden:!app.amountVisible},...[['gross_profit','经营毛利'],['cost_adjustments','回补成本差异'],['opening_inventory_value','期初库存金额'],['closing_inventory_value','期末库存金额'],['average_inventory_value','平均库存金额']].map(([key,label])=>({key,label,type:'money',minWidth:140,hidden:!app.costVisible})),{key:'inventory_turnover',label:'当期周转次数',minWidth:125,hidden:!app.costVisible},{key:'stock_days',label:'库存周转天数',minWidth:125,hidden:!app.costVisible}]
  if(category.value==='inventory_count')return [{key:'number',label:'盘点单号',type:'link',minWidth:210},{key:'date',label:'日期',width:105},{key:'warehouse_name',label:'仓库'},{key:'product_name',label:'商品',minWidth:170},{key:'batch',label:'批次'},{key:'book_quantity',label:'账面数量',type:'qty'},{key:'actual_quantity',label:'实盘数量',type:'qty'},{key:'delta',label:'盘盈 / 盘亏',type:'qty'},{key:'cost_delta',label:'成本变动',type:'money',hidden:!app.costVisible}]
  if(isBusiness.value)return [{key:'dimension',label:groups.value.find(g=>g.key===group.value)?.name||'统计维度',minWidth:190},{key:'document_count',label:'单据数',width:95},{key:'quantity',label:'净数量',type:'qty'},{key:'amount',label:'净金额',type:'money',hidden:!app.amountVisible},{key:'avg_price',label:'平均单价',type:'qty',hidden:!app.amountVisible},{key:'cost',label:'成本',type:'money',hidden:!app.costVisible},{key:'profit',label:'毛利',type:'money',hidden:!app.costVisible||!isSales.value},{key:'margin',label:'毛利率',hidden:!app.costVisible||!isSales.value}]
  if(category.value==='inventory')return [{key:'product_code',label:'商品编码'},{key:'product_name',label:'商品名称',minWidth:180},{key:'warehouse_name',label:'仓库'},{key:'location_name',label:'库位'},{key:'batch',label:'批次'},{key:'quantity',label:'库存数量',type:'qty'},{key:'reserved',label:'订单占用',type:'qty'},{key:'available',label:'可用数量',type:'qty'},{key:'value',label:'库存金额',type:'money',hidden:!app.costVisible}]
  return [{key:'partner_name',label:'往来单位',minWidth:180},...[['current','未到期'],['days_1_30','1–30 天'],['days_31_60','31–60 天'],['days_61_90','61–90 天'],['days_91_180','91–180 天'],['days_180_plus','180 天以上'],['credit','退货贷项'],['total','合计']].map(([key,label])=>({key,label,type:'money',hidden:!app.amountVisible}))]})
const option=computed(()=>({color:['#4a83e7','#56b5a2'],tooltip:{trigger:'axis',valueFormatter:(v:any)=>'¥ '+money(v)},grid:{left:25,right:28,top:24,bottom:20,containLabel:true},xAxis:{type:'category',data:rows.value.slice(0,20).map(r=>r.dimension),axisLine:{lineStyle:{color:'#e5ebf4'}},axisTick:{show:false},axisLabel:{color:'#9daac0',fontSize:10,formatter:(s:string)=>s.length>12?s.slice(0,10)+'…':s}},yAxis:{type:'value',axisLabel:{color:'#9daac0',fontSize:10},splitLine:{lineStyle:{color:'#edf1f7',type:'dashed'}}},series:[{name:'净金额',type:group.value==='date'?'line':'bar',smooth:true,barMaxWidth:28,symbolSize:5,itemStyle:{borderRadius:[4,4,0,0]},lineStyle:{width:2.5},areaStyle:group.value==='date'?{color:'#4a83e711'}:undefined,data:rows.value.slice(0,20).map(r=>Number(r.amount))}]}))
function print(){window.print()}
</script>
<template>
  <div class="page-head"><div><h1>报表中心</h1><p>将采购、销售、库存与往来数据，转化为可核对的经营报表。</p></div><div class="page-actions"><el-button :icon="Printer" @click="print">打印报表</el-button><el-button type="primary" :icon="Download" @click="download('/export?'+query({type:'report',...params()}))">导出报表</el-button></div></div>
  <section class="panel"><div class="panel-tabs"><el-tabs v-model="category"><el-tab-pane v-for="c in categories" :key="c.key" :label="c.name" :name="c.key"/></el-tabs></div><div class="filter-row"><el-select v-if="isBusiness" v-model="group"><el-option v-for="g in groups" :key="g.key" :label="g.name" :value="g.key"/></el-select><el-date-picker v-if="hasDates" v-model="dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" @change="load"/><span v-else class="muted">{{category==='inventory'?'截至当前的库存余额':'截至当前的未核销往来，按到期日计算账龄'}}</span><el-button type="primary" plain :icon="Refresh" @click="load">生成报表</el-button><div class="spacer"></div><span class="muted">{{rows.length}} 组统计记录</span></div>
    <div v-if="isBusiness" class="report-kpis"><div><span>{{isSales?'净销售额':'净采购额'}}</span><strong>¥ {{app.amountVisible?money(totals.amount):'—'}}</strong></div><div><span>净数量</span><strong>{{quantity(totals.quantity)}}</strong></div><div v-if="isSales && app.costVisible"><span>单据毛利</span><strong>¥ {{money(totals.profit)}}</strong></div><div v-if="isSales && app.costVisible"><span>毛利率</span><strong>{{totals.amount?(totals.profit/totals.amount*100).toFixed(2):'0.00'}}%</strong></div></div>
    <Chart v-if="isBusiness && app.amountVisible && rows.length" :option="option" :height="260"/><p v-if="isBusiness" class="chart-note" style="padding-top:10px">统计已审核业务，退货按负数计入；图表展示前 20 组，表格与导出包含全部结果。销售毛利以单据成本计算，负库存回补差异单独体现在工作台经营毛利中。</p>
    <p v-if="category==='operations'" class="hint-box" style="margin:0 22px 20px">回款率＝当期净收款 / 当期净销售，包含预收与历史回款，可能超过 100%。周转次数＝当期销售成本 / 期初期末平均库存；周转天数按所选期间的实际天数计算。库存金额按业务日期汇总完整库存流水。</p>
    <DataTable :rows="rows" :columns="columns" :loading="busy" empty="所选范围暂无已审核业务数据" @open="id=>app.openDoc(id)"/>
  </section>
</template>
